mapper.sql:
WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})


        AND sales_orders.status = #{filter.status}


        AND sales_orders.status > 0


AND location_group_id IN (SELECT location_group_id FROM user_location_groups WHERE user_id = #{userId})

    AND (
        so_code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND sales_orders.order_date >= #{filter.dateFrom}


    AND sales_orders.order_date <= #{filter.dateTo}


    AND sales_orders.status = #{filter.status}


    AND sales_orders.created_by = #{filter.createdBy}


    AND sales_orders.company_id = #{filter.companyId}


    AND sales_orders.location_group_id = #{filter.warehouseId}


    AND sales_orders.customer_id = #{filter.organizationId}


    AND sales_orders.customer_id IN (SELECT customer_id FROM customer_cgroups WHERE cgroup_id = #{filter.organizationGroupId})

mapper.select:
SELECT (SELECT id FROM cgroups WHERE id=(SELECT cgroup_id FROM customer_cgroups WHERE customer_id=sales_orders.customer_id AND cgroup_id IN (SELECT id FROM cgroups WHERE is_active = 1) LIMIT 1)) AS organizationGroupId, (SELECT name FROM cgroups WHERE id=(SELECT cgroup_id FROM customer_cgroups WHERE customer_id=sales_orders.customer_id AND cgroup_id IN (SELECT id FROM cgroups WHERE is_active = 1) LIMIT 1)) AS organizationGroupName, sales_orders.order_date AS orderDate, sales_orders.so_code AS invoiceCode, sales_orders.memo AS memo, CONCAT_WS(' ', customers.customer_code, ' - ', customers.name) AS organizationName, IF(balance > 0 AND DATEDIFF(now(), due_date) > 0, DATEDIFF(now(), due_date), '.') AS aging, sales_orders.total_amount - IFNULL(sales_orders.discount, 0) + IFNULL(sales_orders.total_vat, 0) - IFNULL(sales_orders.total_deposit, 0) AS totalAmount, sales_orders.balance AS balance, sales_orders.status AS status FROM sales_orders INNER JOIN customers ON customers.id = sales_orders.customer_id
ORDER BY organizationGroupName, sales_orders.order_date ASC, sales_orders.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
